You are working in /tmp/sv-3678441651994f7db49ecb4080621b0d/ShipmentTracker - a Blazor Web App solution with two projects:
- ShipmentTracker (server project) at ShipmentTracker/
- ShipmentTracker.Client (WASM client project) at ShipmentTracker.Client/

The app uses Interactive Auto render mode (Server + WebAssembly), Individual accounts auth with ASP.NET Identity (SQLite), and has the standard template files.

Please implement the following shipment tracking features:

## 1. Shared Models (in Client project so both server and WASM can use them)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

## 2. Server-side Entity and DbContext

Create `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class Shipment
{
    public int Id { get; set; }

    [Required]
    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required]
    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required]
    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }

    [Required]
    [MaxLength(256)]
    public string CustomerEmail { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}
```

Update `ShipmentTracker/Data/ApplicationDbContext.cs`:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);
        builder.Entity<Shipment>().HasIndex(s => s.TrackingNumber).IsUnique();
        builder.Entity<Shipment>().HasIndex(s => s.CustomerEmail);
    }
}
```

## 3. API Endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // Dispatcher: get all shipments
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedDate)
                .Select(s => MapToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Dispatcher: create shipment
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (ShipmentDto dto, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = Data.ShipmentStatus.Pending,
                CreatedDate = DateTime.UtcNow,
                EstimatedDelivery = dto.EstimatedDelivery,
                CustomerEmail = dto.CustomerEmail,
                Description = dto.Description
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", MapToDto(shipment));
        });

        // Dispatcher: update shipment status
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, ShipmentStatusUpdate update, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)update.Status;
            if (update.Status == Client.Models.ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(MapToDto(shipment));
        });

        // Customer: track by tracking number
        group.MapGet("/track/{trackingNumber}", [Authorize] async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(MapToDto(shipment));
        });

        // Customer: get my shipments
        group.MapGet("/my", [Authorize] async (HttpContext context, ApplicationDbContext db) =>
        {
            var email = context.User.Identity?.Name ?? string.Empty;
            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.CreatedDate)
                .Select(s => MapToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP{DateTime.UtcNow:yyyyMMdd}{Random.Shared.Next(100000, 999999)}";
    }
}

public record ShipmentStatusUpdate(Client.Models.ShipmentStatus Status);
```

## 4. Update Program.cs

Edit `ShipmentTracker/Program.cs` to add roles and map endpoints. Add after `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();`:

```csharp
builder.Services.AddRoles<IdentityRole>();
```

And update the Identity configuration to add roles:
```csharp
builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddRoles<IdentityRole>()
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();
```

Add before `app.Run();`:
```csharp
// Seed roles
using (var scope = app.Services.CreateScope())
{
    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    string[] roles = ["Dispatcher", "Customer"];
    foreach (var role in roles)
    {
        if (!await roleManager.RoleExistsAsync(role))
            await roleManager.CreateAsync(new IdentityRole(role));
    }
}

app.MapShipmentEndpoints();
```

Also add `using Microsoft.AspNetCore.Identity;` and `using ShipmentTracker.Endpoints;` at the top.

## 5. Client Pages

Create `ShipmentTracker.Client/Pages/Dispatch.razor`:
```razor
@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http
@rendermode InteractiveAuto

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Shipment Dispatch</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreate)
{
    <div class="card mb-4 p-3">
        <h4>Create Shipment</h4>
        <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="CreateShipment">
            <DataAnnotationsValidator />
            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
